local a=require("core.log")local b=require("rules.blacklist_presence")local c={}local d=a.new("rule_engine")local e={}local f={{name="blacklist_presence",module=b}}function c.loadConfig(g)e={}for h,i in ipairs(f)do local j=i.name;local k=i.module;if type(k)~="table"then d.error("Rule '"..j.."' must return a table")else local l,m=true,nil;if type(k.loadConfig)=="function"then l,m=pcall(k.loadConfig,(g or{})[j])end;if l then e[#e+1]={name=j,module=k}d.info("Loaded rule '"..j.."'")else d.error("Could not configure rule '"..j.."': "..tostring(m))end end end end;function c.onSnapshot(n)for h,i in ipairs(e)do local o,m=pcall(i.module.onSnapshot or function()end,n)if not o then d.error("Rule '"..i.name.."' failed: "..tostring(m))end end end;function c.shutdown()for h,i in ipairs(e)do if type(i.module.shutdown)=="function"then local o,m=pcall(i.module.shutdown)if not o then d.error("Rule '"..i.name.."' shutdown failed: "..tostring(m))end end end end;return c
